function sayHi() {
  console.log("Привет!");
}
sayHi();
sayHi(); // выведет «Привет!» два раза

function add(a, b) { // a и b — параметры
  return a + b;
}
add(2, 3); // 2 и 3 — аргументы

function double(n) {
  return n * 2;
}
const result = double(5); // result = 10

function hello() {
  console.log("Привет");
}
const x = hello(); // x === undefined

const square = function (n) {
  return n * n;
};
square(4); // 16

function test() {
  const secret = 42;
}
test();
console.log(secret); // ошибка: снаружи не видно

const appName = "TrainBrain"; // глобальная
function show() {
  console.log(appName); // видна внутри функции
}

function greet(name = "друг") {
  console.log("Привет, " + name);
}
greet();        // Привет, друг
greet("Аня");   // Привет, Аня

const hello = () => console.log("Привет");
const copy = hello; // копия ссылки на функцию
copy();             // Привет

function hi() { return "Привет"; }
hi;   // сама функция, ничего не запущено
hi(); // "Привет"

function a() { console.log(5); }
function b() { return 5; }
const x = a(); // x = undefined
const y = b(); // y = 5

function countdown(n) {
  if (n === 0) return;
  console.log(n);
  countdown(n - 1);
}
countdown(3); // 3, 2, 1
